def _ffn_kernel(x_ref, w1_ref, w2_ref, o_ref, xb_ref):
    j = pl.program_id(1)

    @pl.when(j == 0)
    def _():
        xb_ref[...] = x_ref[0].astype(jnp.bfloat16)

    w1 = w1_ref[0].astype(jnp.bfloat16)
    h = jnp.dot(xb_ref[...], w1, preferred_element_type=jnp.float32)
    h = jax.nn.gelu(h, approximate=True)
    hb = h.astype(o_ref.dtype).astype(jnp.bfloat16)
    w2 = w2_ref[0].astype(jnp.bfloat16)
    y = jnp.dot(hb, w2, preferred_element_type=jnp.float32)

