import jax
import jax.numpy as jnp
from jax import lax

CONFIG = {
    'name': 'SimBasedLoss_3929',
    # torch .T on 4D reverses all axes; matmul (B,C,H,W)@(W,H,C,B) needs B == C == H == W.
    'n': 64,
    'eps': 1e-12,
}


