def _positive_k(k, n):
    # Mirrors TopKMaxPooling.get_positive_k (Python round, i.e. banker's rounding).
    if k <= 0:
        return 0
    if k < 1:
        return round(k * n)
    if k > n:
        return int(n)
    return int(k)


