from jax.experimental.pallas import tpu as pltpu


def _hat_weights(rows, cols, scale):
    pos = jax.lax.broadcasted_iota(jnp.int32, (rows, cols), 0).astype(jnp.float32) * jnp.float32(scale)
    src = jax.lax.broadcasted_iota(jnp.int32, (rows, cols), 1).astype(jnp.float32)
    return jnp.maximum(1.0 - jnp.abs(pos - src), 0.0)


