    b = pl.program_id(0)
    c = pl.program_id(1)

    @pl.when((b == 0) & (c == 0))
    def _():
        ah_ref[...] = _hat_weights(ah_ref.shape[0], ah_ref.shape[1], scale_h)
        aw_ref[...] = _hat_weights(aw_ref.shape[0], aw_ref.shape[1], scale_w)

    @pl.when(c < nx)
    def _():
        ah = ah_ref[...]
        aw = aw_ref[...]
        for ch in range(nc):
            t = jax.lax.dot_general(
                x_ref[0, ch].astype(jnp.float32),
                aw,
                (((1,), (1,)), ((), ())),
                precision=jax.lax.Precision.HIGHEST,
                preferred_element_type=jnp.float32,
            )
            z = jax.lax.dot_general(
                ah,
                t,
                (((1,), (0,)), ((), ())),
                precision=jax.lax.Precision.HIGHEST,
                preferred_element_type=jnp.float32,
            )
            o_ref[0, ch] = z.astype(o_ref.dtype)

